tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "get_unplaced_requirements",
    "description": "Die neuen Requirements, die noch keinem PBI zugeordnet sind (requirementId, text, featureHint).",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "list_features",
    "description": "Bestehende Features (featureId, label) als moegliche Ziele fuer NEW_PBI.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "get_feature_pbis",
    "description": "Die PBIs eines Features (pbiId, title, coveredRequirementIds) - Kandidaten fuer EXTEND_PBI.",
    "parameters": {
      "type": "object",
      "properties": {
        "featureId": {
          "type": "string"
        }
      },
      "required": [
        "featureId"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_pbi",
    "description": "Liest ein PBI (Titel, goal, acceptanceCriteria, linkedRequirementIds).",
    "parameters": {
      "type": "object",
      "properties": {
        "pbiId": {
          "type": "string"
        }
      },
      "required": [
        "pbiId"
      ]
    }
  },
  {
    "type": "function",
    "name": "save_placements",
    "description": "Speichert je unplaced Requirement GENAU EINE Platzierung: kind=EXTEND_PBI (mit pbiId, bestehendes PBI) ODER NEW_PBI (mit featureId, bestehendes Feature) ODER NEW_FEATURE (mit proposedFeatureLabel, wenn KEIN bestehendes Feature fachlich passt). Genau einmal.",
    "parameters": {
      "type": "object",
      "properties": {
        "placements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "kind": {
                "type": "string"
              },
              "requirementId": {
                "type": "string"
              },
              "pbiId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "featureId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "replacementRequirementId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "openDecisionRef": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "rationale": {
                "type": "string"
              },
              "proposedFeatureLabel": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              }
            },
            "required": [
              "kind",
              "requirementId",
              "pbiId",
              "featureId",
              "replacementRequirementId",
              "openDecisionRef",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "placements"
      ]
    }
  }
]

